const $=s=>document.querySelector(s);let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
document.querySelectorAll('[data-minutes]').forEach(b=>b.addEventListener('click',()=>{const n=Number(b.dataset.minutes);document.querySelectorAll('[data-minutes]').forEach(x=>x.classList.toggle('selected',x===b));$('#scheduleNumber').textContent=n>=60?n/60:n;$('#scheduleUnit').textContent=n>=60?'цаг тутам':'минут тутам';$('#scheduleExplanation').textContent=`${n>=60?n/60+' цаг':n+' минут'} тутам шинэ ээлж төлөвлөнө.`;$('.clock-hand').style.transform=`rotate(${n*3+55}deg)`;}));
const steps=[{title:'Chrome Web Store нээнэ.',text:'Албан ёсны Chrome Web Store хуудсыг нээгээд RAINY FB Pro өргөтгөлийг сонгоно.',art:'<div class="art-file">◉</div>',action:'<a class="button primary" href="https://chromewebstore.google.com/detail/ajnokkmlkidbnbihhdgjpbfaepaepbkh" target="_blank" rel="noopener">Chrome Web Store нээх <span>↗</span></a>'},{title:'Add to Chrome дарна.',text:'Өргөтгөлийн Store хуудсан дээрх “Add to Chrome” товчийг дарж суулгалтыг эхлүүлнэ.',art:'<div class="browser-art"><small>CHROME WEB STORE</small><span>RAINY FB Pro<br><br>＋ Add to Chrome</span></div>',action:'<a class="button primary" href="https://chromewebstore.google.com/detail/ajnokkmlkidbnbihhdgjpbfaepaepbkh" target="_blank" rel="noopener">Store хуудас руу очих <span>↗</span></a>'},{title:'Зөвшөөрлийг баталгаажуул.',text:'Chrome-оос гарч ирэх баталгаажуулах цонхонд “Add extension” дарна. Суулгалт дуусахыг хүлээнэ.',art:'<div class="browser-art"><small>CHROME CONFIRMATION</small><span>RAINY FB Pro<br><br>✓ Add extension</span></div>',action:'<a class="button primary" href="https://chromewebstore.google.com/detail/ajnokkmlkidbnbihhdgjpbfaepaepbkh" target="_blank" rel="noopener">Store нээх <span>↗</span></a>'},{title:'Pin хийгээд RAINY-г нээгээрэй.',text:'Chrome-ийн puzzle дүрс → RAINY FB Pro → Pin. RAINY icon-оо дараад Facebook-д нэвтэрсэн tab-аа нээнэ. Trial дуусах огноо дээд хэсэгт харагдана.',art:'<div class="browser-art"><small>CHROME TOOLBAR</small><span>◈ Extensions → RAINY → Pin ✓<br><br>Нийтлэл · Групп · Хуваарь</span></div>',action:'<a class="button primary" href="#help">Зөвлөмж харах <span>↗</span></a>'}];
function setStep(index){const s=steps[index];document.querySelectorAll('[data-step]').forEach(b=>{const a=Number(b.dataset.step)===index;b.classList.toggle('active',a);b.setAttribute('aria-selected',String(a));});$('#stepKicker').textContent='АЛХАМ 0'+(index+1);$('#stepTitle').textContent=s.title;$('#stepText').textContent=s.text;$('#installArt').innerHTML=s.art;$('#stepAction').innerHTML=s.action;$('#nextInstall')?.addEventListener('click',()=>setStep(2));$('#copyChrome')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText('chrome://extensions');toast('Хууллаа. Chrome-ийн хаягийн мөрөнд paste хийнэ үү.');}catch{toast('Chrome-ийн хаягийн мөрөнд chrome://extensions гэж бичнэ үү.');}});}
document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>setStep(Number(b.dataset.step))));setStep(0);
$('.mobile-menu').addEventListener('click',()=>{const open=$('header nav').classList.toggle('open');$('.mobile-menu').setAttribute('aria-expanded',String(open));});document.querySelectorAll('header nav a').forEach(a=>a.addEventListener('click',()=>{$('header nav').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');}));
if('IntersectionObserver'in window){document.documentElement.classList.add('js-reveal');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));}

const imageDialog=$('#imageDialog');document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{$('#largeImage').src=b.dataset.image;imageDialog.showModal();}));$('#closeImage').addEventListener('click',()=>imageDialog.close());imageDialog.addEventListener('click',e=>{if(e.target===imageDialog)imageDialog.close();});
